llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Zalcitabine, a dideoxynucleoside, had absolute oral bioavailability of 80% (range 54–127%) in fasting patients with advanced HIV infection, directly showing that small polar nucleoside analogues can exceed the 20% threshold in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Didanosine, a purine dideoxynucleoside, had median F of 0.28 in fasting patients at 50 mg/m2, above the 20% threshold despite its acid lability, supporting adequate fasted oral absorption for purine nucleoside analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Didanosine fasting F was 0.22 at 150 mg/m2, still above 20%, reinforcing that purine nucleoside analogues meet the threshold under fasting conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "OGT 719, a nucleoside analogue, had overall oral bioavailability around 25% in patients, above the 20% threshold, indicating that even lower-absorbed nucleosides clear the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A pyrazolopyrimidinone with a fused pyrimidinone heterocycle had 34% bioavailability in healthy volunteers in the fasted state, supporting high F for this purine-like scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence, especially fasting nucleoside analogues, shows oral bioavailability at or above 20%, with most values between 25% and 90%. No fasted-state evidence affirmatively supports F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule in humans.",
    "Didanosine fed-state low F values are not transferable to the fasted condition.",
    "The impact of the two hydroxymethyl groups and cyclobutane scaffold on intestinal permeability and transporter-mediated absorption is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

